<?php
declare(strict_types=1);use PHPUnit\Framework\TestCase;use Acorn\SafetyHealthcheck\Domain\{AnswerValue,OverallStatus};final class DomainValuesTest extends TestCase{public function test_status():void{self::assertSame('priority_actions_identified',OverallStatus::fromCounts(1,0));self::assertSame('several_areas_to_review',OverallStatus::fromCounts(0,3));self::assertSame('some_areas_to_review',OverallStatus::fromCounts(0,2));self::assertSame('no_obvious_gaps',OverallStatus::fromCounts(0,0));}public function test_invalid():void{$this->expectException(InvalidArgumentException::class);AnswerValue::assert('compliant');}}
